"""Generate or verify committed HIYELX protobuf Python output."""

from __future__ import annotations

import argparse
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[1]
PROTO_SOURCE = PROJECT_ROOT / "proto/hiyelx/v1/motor.proto"
TARGET_DIRECTORY = PROJECT_ROOT / "src/hiyelx/rpc/generated"
VIRTUAL_PROTO = Path("hiyelx/rpc/generated/motor.proto")
GENERATED_FILES = (
    "motor_pb2.py",
    "motor_pb2.pyi",
    "motor_pb2_grpc.py",
    "motor_pb2_grpc.pyi",
)

GRPC_STUB = """\
# Generated by scripts/generate_proto.py. DO NOT EDIT.

import grpc.aio

from hiyelx.rpc.generated import motor_pb2 as motor__pb2

class MotorServiceStub:
    ListMotors: grpc.aio.UnaryUnaryMultiCallable[
        motor__pb2.ListMotorsRequest, motor__pb2.ListMotorsResponse
    ]
    GetMotorState: grpc.aio.UnaryUnaryMultiCallable[
        motor__pb2.GetMotorStateRequest, motor__pb2.GetMotorStateResponse
    ]
    ApplyMotorCommand: grpc.aio.UnaryUnaryMultiCallable[
        motor__pb2.ApplyMotorCommandRequest, motor__pb2.ApplyMotorCommandResponse
    ]
    StopMotor: grpc.aio.UnaryUnaryMultiCallable[
        motor__pb2.StopMotorRequest, motor__pb2.StopMotorResponse
    ]
    def __init__(self, channel: grpc.aio.Channel) -> None: ...

class MotorServiceServicer:
    async def ListMotors(
        self,
        request: motor__pb2.ListMotorsRequest,
        context: grpc.aio.ServicerContext[
            motor__pb2.ListMotorsRequest, motor__pb2.ListMotorsResponse
        ],
    ) -> motor__pb2.ListMotorsResponse: ...
    async def GetMotorState(
        self,
        request: motor__pb2.GetMotorStateRequest,
        context: grpc.aio.ServicerContext[
            motor__pb2.GetMotorStateRequest, motor__pb2.GetMotorStateResponse
        ],
    ) -> motor__pb2.GetMotorStateResponse: ...
    async def ApplyMotorCommand(
        self,
        request: motor__pb2.ApplyMotorCommandRequest,
        context: grpc.aio.ServicerContext[
            motor__pb2.ApplyMotorCommandRequest, motor__pb2.ApplyMotorCommandResponse
        ],
    ) -> motor__pb2.ApplyMotorCommandResponse: ...
    async def StopMotor(
        self,
        request: motor__pb2.StopMotorRequest,
        context: grpc.aio.ServicerContext[
            motor__pb2.StopMotorRequest, motor__pb2.StopMotorResponse
        ],
    ) -> motor__pb2.StopMotorResponse: ...

def add_MotorServiceServicer_to_server(
    servicer: MotorServiceServicer,
    server: grpc.aio.Server,
) -> None: ...
"""


def generate(output_root: Path) -> Path:
    """Generate protobuf modules beneath a temporary output root."""
    include_root = output_root / "include"
    virtual_source = include_root / VIRTUAL_PROTO
    virtual_source.parent.mkdir(parents=True)
    shutil.copyfile(PROTO_SOURCE, virtual_source)

    generated_root = output_root / "generated"
    generated_root.mkdir()
    command = [
        sys.executable,
        "-m",
        "grpc_tools.protoc",
        f"--proto_path={include_root}",
        f"--python_out={generated_root}",
        f"--pyi_out={generated_root}",
        f"--grpc_python_out={generated_root}",
        str(VIRTUAL_PROTO),
    ]
    completed = subprocess.run(command, check=False)
    if completed.returncode != 0:
        msg = f"protobuf generation failed with exit code {completed.returncode}"
        raise RuntimeError(msg)

    output_directory = generated_root / VIRTUAL_PROTO.parent
    (output_directory / "motor_pb2_grpc.pyi").write_text(GRPC_STUB, encoding="utf-8")
    return output_directory


def check_generated(expected_directory: Path) -> bool:
    """Return whether committed output exactly matches regenerated output."""
    current = True
    for filename in GENERATED_FILES:
        expected = expected_directory / filename
        committed = TARGET_DIRECTORY / filename
        if not committed.is_file() or committed.read_bytes() != expected.read_bytes():
            print(f"stale generated file: {committed.relative_to(PROJECT_ROOT)}")
            current = False
    return current


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--check",
        action="store_true",
        help="verify committed generated files without modifying them",
    )
    arguments = parser.parse_args()

    with tempfile.TemporaryDirectory(prefix="hiyelx-proto-") as temporary:
        expected_directory = generate(Path(temporary))
        if arguments.check:
            return 0 if check_generated(expected_directory) else 1

        TARGET_DIRECTORY.mkdir(parents=True, exist_ok=True)
        for filename in GENERATED_FILES:
            shutil.copyfile(
                expected_directory / filename,
                TARGET_DIRECTORY / filename,
            )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
